local a=peripheral.find("modem")local b=require("index")local c={}local function d(e)local f=a.callRemote(e,"size")for g=1,f do local h=a.callRemote(e,"getItemDetail",g)if h==nil then return true end end;return false end;local function i(j,k,g,l)local m,n=b.getReceiver(l,j)if m==nil then return end;if d(m)then a.callRemote(k,"pushItems",m,g)print("Transferred from "..k.." to "..n)else print("No empty slots available in receiver "..n)end end;local function o(p,l)for g,h in pairs(a.callRemote(p,"list"))do if h==nil then goto q end;local r=a.callRemote(p,"getItemDetail",g)local s=r.package;if s==nil then i("MainItem",p,g,l)else local j=s.getAddress()if j~=nil then i(j,p,g,l)else print("No address found for item in slot "..g.." of sender "..p)end end::q::end end;function c.logisticsLoop(l)while true do local t=b.getAllSenders(l)if#t==0 then print("No senders found in index.")sleep(5)break end;for u,p in ipairs(t)do o(p,l)end end end;return c
